GIF_st.name='GIF'; 
GIF_st.lat=48.71;
GIF_st.lon=2.15;
GIF_st.alt=160;
GIF_st.env='con';
GIF_st.footp='U';
%%
GIF_rd=read_ebas_merged_STN('C:\github_trend\raw_data\merged_SIRTA Atmospheric Research Observatory.nc', GIF_st);

names_rd=fieldnames(GIF_rd);

%%
datevec(GIF_rd.Time(1)) % begin in 2010 %[output:8271a9ab]
datevec(GIF_rd.Time(end)) % end in 2025 %[output:1550d4df]
 prctile(GIF_rd.U370_S,[5 50 95]) % < 50%, compute RH trend and _dry %[output:0a3fe14d]
% % prctile(GIF_rd.U0_S11,[5 50 95])
plotFigControl(GIF_rd,GIF_st.name); %[output:27fe4af4] %[output:66dc9c60] %[output:62d69be7] %[output:99807cc3] %[output:941c7282] %[output:379ad78b] %[output:933d6386] %[output:1169ae47]
%%
% BP detection for scat coef and backscat

names_abs={'BaR_Amaap'};
break_GIF_abs_BP=change_point_analysis_Def(GIF_rd,names_abs,0.05,'GIF','Absorption MAAP');
T_GIF_abs_BP=make_table_breakpoints_def(break_GIF_abs_BP);
%%
% use MAAP data as it, 
%rGIFmpute trend after answer if AE or 2025 are available
GIF_tr=GIF_rd;
GIF_tr.eBC__g_m3_=[];
%convert in Mm
GIF_tr.BaR_Amaap=GIF_tr.BaR_Amaap*1e6;
%%
[GIF_result_MK,GIF_result_LMSlog,GIF_result_LMSlin]=all_trend_STN(GIF_tr,GIF_st);

writetable(GIF_result_MK,'GIF_res_MK.txt'); %, 'delimiter',',' )
writetable(GIF_result_LMSlog,'GIF_res_LMSlog.txt'); 
writetable(GIF_result_LMSlin,'GIF_res_LMSlin.txt'); 
plot_10y_in_two(GIF_result_MK, GIF_st,'y');


